# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">PEYGAMBERİMİZİN ÇOCUKLUK YILLARI ZAMAN ŞERİDİ</text>\n  <rect x="20" y="48" width="155" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="97" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">0 - 4 Yaş</text>\n  <text x="97" y="96" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">Sütanne Hz. Halime</text>\n  <text x="97" y="120" text-anchor="middle" font-size="11" fill="#334155">Sa\'d kabilesi yurdunda</text>\n  <text x="97" y="138" text-anchor="middle" font-size="11" fill="#334155">sağlıklı büyüme, fasih</text>\n  <text x="97" y="156" text-anchor="middle" font-size="11" fill="#334155">Arapça ve bereket.</text>\n  <text x="97" y="185" text-anchor="middle" font-size="11" font-weight="bold" fill="#2563eb">Süt Kardeşler:</text>\n  <text x="97" y="203" text-anchor="middle" font-size="10" fill="#475569">Abdullah, Üneyse, Şeyma</text>\n\n  <rect x="188" y="48" width="155" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="265" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">4 - 6 Yaş</text>\n  <text x="265" y="96" text-anchor="middle" font-size="12" font-weight="bold" fill="#14532d">Annesi Hz. Âmine</text>\n  <text x="265" y="120" text-anchor="middle" font-size="11" fill="#334155">Mekke\'de annesinin</text>\n  <text x="265" y="138" text-anchor="middle" font-size="11" fill="#334155">şefkatli himayesi;</text>\n  <text x="265" y="156" text-anchor="middle" font-size="11" fill="#334155">Medine ziyareti ve</text>\n  <text x="265" y="174" text-anchor="middle" font-size="11" fill="#334155">dönüşte Ebvâ köyünde</text>\n  <text x="265" y="192" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">Hz. Âmine\'nin vefatı.</text>\n\n  <rect x="356" y="48" width="155" height="190" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <text x="433" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">6 - 8 Yaş</text>\n  <text x="433" y="96" text-anchor="middle" font-size="12" font-weight="bold" fill="#713f12">Dedesi Abdülmuttalip</text>\n  <text x="433" y="120" text-anchor="middle" font-size="11" fill="#334155">Ümmü Eymen ile Mekke\'ye</text>\n  <text x="433" y="138" text-anchor="middle" font-size="11" fill="#334155">dönüş; dedesinin Kâbe</text>\n  <text x="433" y="156" text-anchor="middle" font-size="11" fill="#334155">gölgesindeki özel</text>\n  <text x="433" y="174" text-anchor="middle" font-size="11" fill="#334155">mindere oturtulması;</text>\n  <text x="433" y="192" text-anchor="middle" font-size="11" font-weight="bold" fill="#854d0e">8 yaşında dedenin vefatı.</text>\n\n  <rect x="524" y="48" width="156" height="190" rx="8" fill="#faf5ff" stroke="#a855f7" stroke-width="1.5"/>\n  <text x="602" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#7e22ce">8 Yaş ve Sonrası</text>\n  <text x="602" y="96" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">Amcası Ebû Talip</text>\n  <text x="602" y="120" text-anchor="middle" font-size="11" fill="#334155">Amcası Ebû Talip ve</text>\n  <text x="602" y="138" text-anchor="middle" font-size="11" fill="#334155">yengesi Fatıma binti</text>\n  <text x="602" y="156" text-anchor="middle" font-size="11" fill="#334155">Esed\'in sıcak yuvası;</text>\n  <text x="602" y="174" text-anchor="middle" font-size="11" fill="#334155">çobanlık ve ticaret</text>\n  <text x="602" y="192" text-anchor="middle" font-size="11" font-weight="bold" fill="#7e22ce">yolculuğu tecrübesi.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">PEYGAMBERİMİZİ BÜYÜTEN MÜBAREK HANIMLAR VE SÜT AİLESİ</text>\n  <rect x="25" y="48" width="310" height="190" rx="8" fill="#fff1f2" stroke="#f43f5e" stroke-width="1.5"/>\n  <text x="180" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#be123c">Şefkat ve Vefa Örnekleri</text>\n  <text x="45" y="100" font-size="12" font-weight="bold" fill="#9f1239">• Hz. Âmine: Öz annesi (İlk süt veren).</text>\n  <text x="45" y="126" font-size="12" font-weight="bold" fill="#9f1239">• Süveybe Hatun: İlk emziren sütannesi.</text>\n  <text x="45" y="152" font-size="12" font-weight="bold" fill="#9f1239">• Hz. Halime: Sa\'d kabilesinden sütannesi.</text>\n  <text x="45" y="178" font-size="12" font-weight="bold" fill="#9f1239">• Ümmü Eymen: Dadısı ("Annemden sonra annem").</text>\n  <text x="45" y="204" font-size="12" font-weight="bold" fill="#9f1239">• Fatıma binti Esed: Şefkatli yengesi.</text>\n\n  <rect x="365" y="48" width="310" height="190" rx="8" fill="#ecfeff" stroke="#06b6d4" stroke-width="1.5"/>\n  <text x="520" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#0e7490">Sütanne Geleneğinin Sebepleri</text>\n  <text x="385" y="102" font-size="12" fill="#334155">1. Mekke\'nin aşırı sıcak ve salgın hastalıklara</text>\n  <text x="395" y="120" font-size="12" fill="#334155">açık havasından bebekleri korumak.</text>\n  <text x="385" y="150" font-size="12" fill="#334155">2. Yayla ve çöl havasında bedenen sağlam,</text>\n  <text x="395" y="168" font-size="12" fill="#334155">özgür ve sağlıklı büyümelerini sağlamak.</text>\n  <text x="385" y="198" font-size="12" fill="#334155">3. Bâdiye kabilelerinin bozulmamış, duru ve</text>\n  <text x="395" y="216" text-anchor="middle" font-size="12" font-weight="bold" fill="#155e75">fasih (düzgün) Arapçasını öğretmek.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">ÇOCUKLUK YILLARINDA PEYGAMBERİMİZİN ÖRNEK AHLAKI</text>\n  <rect x="20" y="48" width="210" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="125" y="74" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Paylaşımcılık ve Kanaat</text>\n  <text x="125" y="104" text-anchor="middle" font-size="11" fill="#334155">Süt kardeşlerinin hakkına</text>\n  <text x="125" y="124" text-anchor="middle" font-size="11" fill="#334155">saygı göstermiş, sofrada</text>\n  <text x="125" y="144" text-anchor="middle" font-size="11" fill="#334155">Besmele ile ve edeple</text>\n  <text x="125" y="164" text-anchor="middle" font-size="11" fill="#334155">yemek yiyerek kanaatkâr</text>\n  <text x="125" y="184" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">bir çocukluk geçirmiştir.</text>\n\n  <rect x="245" y="48" width="210" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="350" y="74" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Çalışkanlık ve Sorumluluk</text>\n  <text x="350" y="104" text-anchor="middle" font-size="11" fill="#334155">Amcası Ebû Talip\'in geçim</text>\n  <text x="350" y="124" text-anchor="middle" font-size="11" fill="#334155">yükünü hafifletmek için</text>\n  <text x="350" y="144" text-anchor="middle" font-size="11" fill="#334155">koyun güderek (çobanlık)</text>\n  <text x="350" y="164" text-anchor="middle" font-size="11" fill="#334155">ve ticaret işlerinde</text>\n  <text x="350" y="184" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">yardımcı olarak çalışmıştır.</text>\n\n  <rect x="470" y="48" width="210" height="190" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <text x="575" y="74" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Büyüklere Vefa ve Saygı</text>\n  <text x="575" y="104" text-anchor="middle" font-size="11" fill="#334155">Yetişmesinde emeği geçen</text>\n  <text x="575" y="124" text-anchor="middle" font-size="11" fill="#334155">Hz. Halime\'ye, Şeyma\'ya,</text>\n  <text x="575" y="144" text-anchor="middle" font-size="11" fill="#334155">Ümmü Eymen\'e ve yengesi</text>\n  <text x="575" y="164" text-anchor="middle" font-size="11" fill="#334155">Fatıma hanıma ömrü boyunca</text>\n  <text x="575" y="184" text-anchor="middle" font-size="11" font-weight="bold" fill="#854d0e">vefa ve hürmet göstermiştir.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
